// CPP_gen_grad1

extern "C" void gen_grad1_to_c(const Opaque_gen_grad1_class*, CPP_gen_grad1&);

// c_side.to_f2_arg
extern "C" void gen_grad1_to_f2(
    Opaque_gen_grad1_class*,
    c_Int&,
    c_Int&,
    c_Int&,
    c_RealArr,
    c_Int,
    c_Int);

extern "C" void gen_grad1_to_f(
    const CPP_gen_grad1& C,
    Opaque_gen_grad1_class* F) {
  // c_side.to_f_setup[2D_ALLOC_real] VariableArray2D<Real>
  size_t n1_deriv{C.deriv.size()};
  size_t n2_deriv{size_t{0}};
  Real* z_deriv = nullptr;
  if (n1_deriv > 0) {
    n2_deriv = C.deriv[0].size();
    z_deriv = new Real[n1_deriv * n2_deriv];
    matrix_to_vec(C.deriv, z_deriv);
  }

  // c_side.to_f2_call
  gen_grad1_to_f2(F, C.m, C.sincos, C.n_deriv_max, z_deriv, n1_deriv, n2_deriv);

  // c_side.to_f_cleanup[2D_ALLOC_real]
  if (z_deriv)
    delete[] z_deriv;
}

// c_side.to_c2_arg
extern "C" void gen_grad1_to_c2(
    CPP_gen_grad1& C,
    c_Int& z_m,
    c_Int& z_sincos,
    c_Int& z_n_deriv_max,
    c_RealArr z_deriv,
    c_Int n1_deriv,
    c_Int n2_deriv) {
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.m = z_m;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.sincos = z_sincos;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_deriv_max = z_n_deriv_max;
  // c_side.to_c2_set[2D_ALLOC_real] VariableArray2D<Real>
  C.deriv.resize(n1_deriv);
  for (size_t i{0}; i < n1_deriv; i++)
    C.deriv[i].resize(n2_deriv);
  C.deriv << z_deriv;
}

