  C.y_knot.resize(n1_y_knot);
  C.y_knot << z_y_knot;
  // c_side.to_c2_set[1D_ALLOC_type] VariableArray1D<CPP_expression_atom>
  C.stack.resize(n1_stack);
  for (size_t i{0}; i < n1_stack; i++) {
    expression_atom_to_c(z_stack[i], C.stack[i]);
  }
  // c_side.to_c2_set[0D_NOT_type] CPP_lat_ele_loc
  lat_ele_loc_to_c(z_slave, C.slave);
  // c_side.to_c2_set[0D_NOT_type] CPP_lat_ele_loc
  lat_ele_loc_to_c(z_lord, C.lord);
