extern "C" void controller_to_c2(
    CPP_controller& C,
    Opaque_control_var1_class** z_var,
    c_Int n1_var,
    Opaque_control_ramp1_class** z_ramp,
    c_Int n1_ramp,
    Opaque_ramper_lord_class** z_ramper_lord,
    c_Int n1_ramper_lord,
    c_RealArr z_x_knot,
    c_Int n1_x_knot) {
  // c_side.to_c2_set[1D_ALLOC_type] VariableArray1D<CPP_control_var1>
  C.var.resize(n1_var);
  for (size_t i{0}; i < n1_var; i++) {
    control_var1_to_c(z_var[i], C.var[i]);
  }
  // c_side.to_c2_set[1D_ALLOC_type] VariableArray1D<CPP_control_ramp1>
  C.ramp.resize(n1_ramp);
  for (size_t i{0}; i < n1_ramp; i++) {
    control_ramp1_to_c(z_ramp[i], C.ramp[i]);
  }
  // c_side.to_c2_set[1D_ALLOC_type] VariableArray1D<CPP_ramper_lord>
  C.ramper_lord.resize(n1_ramper_lord);
  for (size_t i{0}; i < n1_ramper_lord; i++) {
    ramper_lord_to_c(z_ramper_lord[i], C.ramper_lord[i]);
  }
  // c_side.to_c2_set[1D_ALLOC_real] VariableArray1D<Real>
  C.x_knot.resize(n1_x_knot);
  C.x_knot << z_x_knot;
}

