  // c_side.to_c2_set[1D_ALLOC_type] VariableArray1D<CPP_coord>
  C.particle.resize(n1_particle);
  for (size_t i{0}; i < n1_particle; i++) {
    coord_to_c(z_particle[i], C.particle[i]);
  }
  // c_side.to_c2_set[1D_ALLOC_integer] VariableArray1D<Int>
  C.ix_z.resize(n1_ix_z);
  C.ix_z << z_ix_z;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.charge_tot = z_charge_tot;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.charge_live = z_charge_live;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.z_center = z_z_center;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.t_center = z_t_center;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.t0 = z_t0;
  // c_side.to_c2_set[0D_NOT_logical] Bool
  C.drift_between_t_and_s = z_drift_between_t_and_s;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.ix_ele = z_ix_ele;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.ix_bunch = z_ix_bunch;
