extern "C" void bunch_params_to_f2(
    Opaque_bunch_params_class*,
    const CPP_coord&,
    const CPP_twiss&,
    const CPP_twiss&,
    const CPP_twiss&,
    const CPP_twiss&,
    const CPP_twiss&,
    const CPP_twiss&,
    c_RealArr,
    c_RealArr,
    c_RealArr,
    c_Real&,
    c_Real&,
    c_Real&,
    c_Real&,
    c_Real&,
    c_Int&,
    c_Int&,
    c_Int&,
    c_Int&,
    c_Int&,
    c_Int&,
    c_Int&,
    c_Bool&);

extern "C" void bunch_params_to_f(
    const CPP_bunch_params& C,
    Opaque_bunch_params_class* F) {
  // c_side.to_f_setup[2D_NOT_real] FixedArray2D<Real, 6, 6>
  Real z_sigma[6 * 6];
  matrix_to_vec(C.sigma, z_sigma);

  // c_side.to_f2_call
  bunch_params_to_f2(
      F,
      C.centroid,
      C.x,
      C.y,
      C.z,
      C.a,
      C.b,
      C.c,
      z_sigma,
      &C.rel_max[0],
      &C.rel_min[0],
      C.s,
      C.t,
      C.sigma_t,
      C.charge_live,
      C.charge_tot,
      C.n_particle_tot,
      C.n_particle_live,
      C.n_particle_lost_in_ele,
      C.n_good_steps,
      C.n_bad_steps,
      C.ix_ele,
      C.location,
      C.twiss_valid);
}

// c_side.to_c2_arg
extern "C" void bunch_params_to_c2(
    CPP_bunch_params& C,
    const Opaque_coord_class* z_centroid,
    const Opaque_twiss_class* z_x,
    const Opaque_twiss_class* z_y,
    const Opaque_twiss_class* z_z,
    const Opaque_twiss_class* z_a,
    const Opaque_twiss_class* z_b,
    const Opaque_twiss_class* z_c,
    c_RealArr z_sigma,
    c_RealArr z_rel_max,
    c_RealArr z_rel_min,
    c_Real& z_s,
    c_Real& z_t,
    c_Real& z_sigma_t,
    c_Real& z_charge_live,
    c_Real& z_charge_tot,
    c_Int& z_n_particle_tot,
    c_Int& z_n_particle_live,
    c_Int& z_n_particle_lost_in_ele,
    c_Int& z_n_good_steps,
    c_Int& z_n_bad_steps,
    c_Int& z_ix_ele,
    c_Int& z_location,
    c_Bool& z_twiss_valid) {
  // c_side.to_c2_set[0D_NOT_type] CPP_coord
  coord_to_c(z_centroid, C.centroid);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_x, C.x);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_y, C.y);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_z, C.z);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_a, C.a);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_b, C.b);
  // c_side.to_c2_set[0D_NOT_type] CPP_twiss
  twiss_to_c(z_c, C.c);
  // c_side.to_c2_set[2D_NOT_real] FixedArray2D<Real, 6, 6>
  C.sigma << z_sigma;
  // c_side.to_c2_set[1D_NOT_real] FixedArray1D<Real, 7>
  C.rel_max << z_rel_max;
  // c_side.to_c2_set[1D_NOT_real] FixedArray1D<Real, 7>
  C.rel_min << z_rel_min;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.s = z_s;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.t = z_t;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.sigma_t = z_sigma_t;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.charge_live = z_charge_live;
  // c_side.to_c2_set[0D_NOT_real] Real
  C.charge_tot = z_charge_tot;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_particle_tot = z_n_particle_tot;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_particle_live = z_n_particle_live;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_particle_lost_in_ele = z_n_particle_lost_in_ele;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_good_steps = z_n_good_steps;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.n_bad_steps = z_n_bad_steps;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.ix_ele = z_ix_ele;
  // c_side.to_c2_set[0D_NOT_integer] Int
  C.location = z_location;
  // c_side.to_c2_set[0D_NOT_logical] Bool
  C.twiss_valid = z_twiss_valid;
}

